import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                pkgs[pkg['id']] = {'requested': pkg.get('requestedVersion',''), 'resolved': pkg.get('resolvedVersion','')}
        result[name] = pkgs
    return result

b = extract(baseline)
a = extract(after)

changes = []
unchanged = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg, {}).get('resolved', '')
        av = ap.get(pkg, {}).get('resolved', '')
        br = bp.get(pkg, {}).get('requested', '')
        ar = ap.get(pkg, {}).get('requested', '')
        if bv != av:
            changes.append((proj, pkg, br, bv, ar, av))
        else:
            unchanged.append((proj, pkg, bv))

print('=== CHANGES ===')
for c in changes:
    print(f'{c[0]} | {c[1]} | {c[2]} -> {c[4]} | resolved {c[3]} -> {c[5]}')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'{u[0]} | {u[1]} | {u[2]}')
"

